enum Light { Red, Amber, Green }

fn phase_of(m: i32) -> Light {
    if m < 90 { Light::Red } else { if m < 180 { Light::Green } else { Light::Amber } }
}

fn lamp(active: bool, on: i32, off: i32) -> i32 {
    if active { on } else { off }
}

fn is_red(l: Light) -> bool {
    match l { Light::Red => true, _ => false }
}

fn is_amber(l: Light) -> bool {
    match l { Light::Amber => true, _ => false }
}

fn is_green(l: Light) -> bool {
    match l { Light::Green => true, _ => false }
}

fn frame(t: i32) {
    let m: i32 = t % 210;
    let l: Light = phase_of(m);
    host::display::clear(0x101010);
    host::display::fill_rect(90, 30, 76, 208, 0x282828);
    host::display::fill_rect(104, 44, 48, 48, lamp(is_red(l), 0xff2020, 0x401010));
    host::display::fill_rect(104, 110, 48, 48, lamp(is_amber(l), 0xffb020, 0x403010));
    host::display::fill_rect(104, 176, 48, 48, lamp(is_green(l), 0x20ff40, 0x104010));
    host::display::present();
}
